function pageEntries(entries, query = {}) {
  const page = parsePage(query);
  if (page === null) return {status: 400, body: {error: "Invalid page"}};
  const ordered = [...entries].sort((a, b) => a.id - b.id);
  return {status: 200, body: ordered.slice(page.offset, page.offset + page.limit)};
}

